const allowed = new Set(ctx.files.map(f=>path.join(ctx.workspace,f)));
const host = ts.createCompilerHost(optionsResult.options, true);
const baseRead = host.readFile;
host.readFile = file => {
 const p = path.resolve(file);
 if (allowed.has(p) || p.startsWith('/opt/typescript/') || p.includes('/node_modules/')) return baseRead(file);
