const entry = program.getSourceFile(path.join(ctx.workspace,'src/index.ts'));
const exp = checker.getExportsOfModule(checker.getSymbolAtLocation(entry)).find(s=>s.name==='getNamedType');
function canonical(s) { return s && (s.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(s) : s); }
const target = canonical(exp);
